<?php require 'app/init.php';require 'app/view.php';$u=require_user();if($_SERVER['REQUEST_METHOD']==='POST'){verify();$bio=trim($_POST['bio']??'');if(mb_strlen($bio)<=1000)db()->prepare('UPDATE usuarios SET bio=? WHERE id=?')->execute([$bio,$u['id']]);go('perfil.php');}$s=db()->prepare('SELECT * FROM usuarios WHERE id=?');$s->execute([$u['id']]);$profile=$s->fetch();top('Mi perfil');?><main class="card" style="max-width:800px;margin:30px auto"><h1><?=e($u['nombre'])?></h1><p class="muted">@<?=e($u['usuario'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><textarea name="bio" maxlength="1000" placeholder="Cuéntanos sobre tus lecturas"><?=e($profile['bio'])?></textarea><p><button>Guardar perfil</button></p></form><h2>Mis publicaciones</h2><?php $s=db()->prepare('SELECT id,titulo,contenido FROM publicaciones WHERE usuario_id=? ORDER BY creado_en DESC');$s->execute([$u['id']]);foreach($s as $p):?><div class="comment"><a href="publicacion.php?id=<?=$p['id']?>"><strong><?=e($p['titulo']?:'Ver publicación')?></strong></a><p><?=e(mb_strimwidth($p['contenido'],0,150,'…'))?></p></div><?php endforeach;?></main><?php bottom();?>